CATS = [
  {'slug': 'buldozery', 'name_nom': 'Бульдозеры', 'name_single': 'Бульдозер', 'h1': 'Аренда бульдозера', 'lead': 'КРАН365 подберёт и подаст бульдозер нужного класса из проверенной партнёрской сети — с оператором, договором и ответственностью за сроки подачи.', 'intro': 'Бульдозеры применяют для планировки и выравнивания площадок, снятия растительного слоя и грунта, засыпки котлованов и траншей, корчёвки, устройства насыпей и черновой разработки грунта. Класс машины подбирают под объём и плотность грунта: лёгкие 10–17 т — для планировки и перемещения грунта на небольшие расстояния, тяжёлые от 20 т — для разработки плотных грунтов и больших объёмов. Опишите задачу — поможем выбрать машину под ваш грунт и график.', 'price_from': 20000, 'items': [{'subslug': 'b10m', 'name': 'Бульдозер ЧТЗ Б10М', 'specs': ['Масса ~15,6 т, 10-й тяговый класс', 'Двигатель 180 л.с.', 'Отвал ~3,2 м, гусеничный ход'], 'price': 20000}, {'subslug': 'shantui-sd16', 'name': 'Бульдозер Shantui SD16', 'specs': ['Масса ~17 т', 'Двигатель 160 л.с.', 'Отвал ~3,4 м, полусферический'], 'price': 22000}, {'subslug': 'komatsu-d65', 'name': 'Бульдозер Komatsu D65', 'specs': ['Масса ~20 т', 'Двигатель ~217 л.с.', 'Отвал ~3,9 м, гидроповорот'], 'price': 32000}, {'subslug': 'cat-d6', 'name': 'Бульдозер Caterpillar D6', 'specs': ['Масса ~20 т', 'Двигатель ~215 л.с.', 'Отвал ~3,9 м, с рыхлителем'], 'price': 34000}, {'subslug': 'shantui-sd22', 'name': 'Бульдозер Shantui SD22', 'specs': ['Масса ~23 т', 'Двигатель 220 л.с.', 'Отвал ~3,9 м, рыхлитель сзади'], 'price': 38000}, {'subslug': 'komatsu-d155', 'name': 'Бульдозер Komatsu D155', 'specs': ['Масса ~40 т, тяжёлый класс', 'Двигатель ~354 л.с.', 'Отвал ~4,7 м, для больших объёмов'], 'price': None}, {'subslug': 'cat-d9', 'name': 'Бульдозер Caterpillar D9', 'specs': ['Масса ~49 т, тяжёлый класс', 'Двигатель ~436 л.с.', 'Разработка скальных и плотных грунтов'], 'price': None}], 'faqs': [['Как быстро подадите бульдозер на объект?', 'По Москве и области — обычно от суток после согласования условий, по регионам срок зависит от площадки и класса машины. Точную дату и время подачи фиксируем в договоре и отвечаем за них.'], ['Аренда с оператором или без?', 'Подаём с опытным машинистом — это стандарт для гусеничной техники. Управление бульдозером требует допуска и навыка, поэтому вариант «без оператора» мы не предлагаем.'], ['Что входит в стоимость смены?', 'Работа машины и оператора в течение смены (обычно 8–10 часов). ГСМ, перебазировка тралом и работа сверх смены считаются отдельно — все эти позиции заранее прописываем, чтобы не было сюрпризов.'], ['Какие документы предоставляете?', 'Договор аренды, счёт, акты выполненных работ, при необходимости — путевые листы и данные машины для оформления пропусков на объект. Работаем с юрлицами и ИП по безналу, с НДС.'], ['Как понять, какой класс бульдозера нужен?', 'Зависит от задачи и грунта: планировка, снятие слоя и перемещение — 10–17 т; тяжёлая разработка, корчёвка и большие объёмы — от 20 т. Опишите объект и объём работ — подберём машину под условия.']]},
  {'slug': 'avtogreidery', 'name_nom': 'Автогрейдеры', 'name_single': 'Автогрейдер', 'h1': 'Аренда автогрейдера', 'lead': 'Организуем аренду автогрейдера под ваш объект: находим машину в проверенной сети партнёров и подаём с опытным машинистом по договору.', 'intro': 'Автогрейдеры нужны для точного профилирования земляного полотна и дорожного основания, планировки больших площадок «под ноль», разравнивания и перемешивания материалов, устройства и содержания грунтовых дорог, очистки территорий и дорог от снега. Главный рабочий орган — поворотный отвал, который выдерживает заданные уклоны и ровность там, где бульдозер уже не даёт нужной точности. Класс подбирают под ширину захвата и плотность материала.', 'price_from': 20000, 'items': [{'subslug': 'gs-14-02', 'name': 'Автогрейдер ГС-14.02 (ДЗ-98)', 'specs': ['Масса ~14,5 т, средний класс', 'Двигатель ~150 л.с.', 'Отвал ~3,74 м, гидроповорот'], 'price': 22000}, {'subslug': 'xcmg-gr165', 'name': 'Автогрейдер XCMG GR165', 'specs': ['Масса ~15,4 т', 'Двигатель 165 л.с.', 'Отвал ~3,96 м'], 'price': 23000}, {'subslug': 'komatsu-gd535', 'name': 'Автогрейдер Komatsu GD535', 'specs': ['Масса ~14 т', 'Двигатель ~135 л.с.', 'Отвал ~3,7 м, точное профилирование'], 'price': 30000}, {'subslug': 'cat-140', 'name': 'Автогрейдер Caterpillar 140', 'specs': ['Масса ~16–18 т', 'Двигатель ~185 л.с.', 'Отвал ~3,7 м, для дорожных работ'], 'price': 35000}, {'subslug': 'dz-122', 'name': 'Автогрейдер ДЗ-122', 'specs': ['Масса ~13,5 т', 'Двигатель ~135 л.с.', 'Отвал ~3,7 м, планировка и содержание дорог'], 'price': 20000}, {'subslug': 'sem-919', 'name': 'Автогрейдер SEM 919', 'specs': ['Масса ~13 т', 'Двигатель ~190 л.с.', 'Отвал ~3,66 м, кирковщик в опции'], 'price': 24000}], 'faqs': [['Для каких работ подходит автогрейдер?', 'Профилирование дорожного полотна и основания, планировка площадок под заданный уклон, разравнивание щебня и грунта, устройство и содержание грунтовых дорог, зимой — очистка от снега. Там, где важна ровность и уклон, грейдер точнее бульдозера.'], ['Подаёте с машинистом?', 'Да, автогрейдер подаём только с опытным машинистом. Работа отвалом «в ноль» и по уклонам требует квалификации, поэтому оператор входит в услугу.'], ['Как быстро можно получить технику?', 'По Москве и области — обычно от суток после согласования, по регионам зависит от наличия ближайшей машины и перебазировки. Срок подачи фиксируем в договоре.'], ['Какие документы оформляете?', 'Договор аренды, счёт, акты, при необходимости — путевые листы и данные для пропусков на объект. Работаем по безналу с юрлицами и ИП, с НДС.'], ['Какой длины отвал выбрать?', 'Для городских и стеснённых площадок берут машину компактнее (отвал ~3,7 м), для широких дорог и больших объёмов — модели с более длинным отвалом и большей мощностью. Опишите фронт работ — подберём класс.']]},
  {'slug': 'dorozhnye-katki', 'name_nom': 'Дорожные катки', 'name_single': 'Дорожный каток', 'h1': 'Аренда дорожного катка', 'lead': 'Подберём и подадим дорожный каток под ваш материал и объём — из проверенной сети партнёров, с оператором и фиксацией сроков в договоре.', 'intro': 'Дорожные катки уплотняют грунт, песчано-щебёночное основание и асфальтобетон при строительстве дорог, площадок, дворов и подъездных путей. Тип катка подбирают под материал: гладковальцовые вибрационные — для грунта и основания, кулачковые — для связных грунтов, двухвальцовые и пневмоколёсные — для укладки и финишного уплотнения асфальта. Массу и ширину вальца выбирают под толщину слоя и площадь.', 'price_from': 10000, 'items': [{'subslug': 'katok-1-5t', 'name': 'Каток тандемный малый ~1,5 т', 'specs': ['Масса ~1,5 т', 'Два вибровальца, ширина ~0,8 м', 'Тротуары, дворы, ямочный ремонт'], 'price': 10000}, {'subslug': 'katok-4t', 'name': 'Каток тандемный ~4 т', 'specs': ['Масса ~4 т', 'Два вибровальца, ширина ~1,3 м', 'Дорожки, парковки, тонкий асфальт'], 'price': 14000}, {'subslug': 'asfalt-10t', 'name': 'Каток асфальтовый ~10 т (Hamm HD90 и аналоги)', 'specs': ['Масса ~9–10 т', 'Два гладких вальца, ширина ~1,68 м', 'Уплотнение асфальтобетона'], 'price': 18000}, {'subslug': 'grunt-12t', 'name': 'Каток грунтовый ~12 т (Bomag BW211 и аналоги)', 'specs': ['Масса ~12 т', 'Гладкий вибровалец, ширина ~2,13 м', 'Грунт и щебёночное основание'], 'price': 20000}, {'subslug': 'kulachkovyy-14t', 'name': 'Каток грунтовый кулачковый ~14 т', 'specs': ['Масса ~14 т', 'Кулачковый (padfoot) валец', 'Связные и глинистые грунты'], 'price': 22000}, {'subslug': 'pnevmo-16t', 'name': 'Каток пневмоколёсный ~16 т', 'specs': ['Масса ~16 т (с балластом)', '7–9 колёс, регулировка давления', 'Финишное уплотнение асфальта'], 'price': 24000}], 'faqs': [['Какой каток нужен под мою задачу?', 'Под грунт и основание берут гладковальцовый вибрационный (10–14 т) или кулачковый для связных грунтов; под асфальт — двухвальцовый и пневмоколёсный для финиша; для дворов и узких мест — малый тандем 1,5–4 т. Опишите материал и площадь — подберём тип и массу.'], ['Каток подаётся с оператором?', 'Да, по умолчанию подаём с машинистом. Для малых тандемных катков в отдельных случаях возможна аренда без оператора — уточняйте при заказе, решим по конкретной машине.'], ['Как подаёте технику и считается ли доставка?', 'Малые катки привозим на эвакуаторе/трале, тяжёлые — тралом. Перебазировка считается отдельно от смены; стоимость доставки зависит от адреса и заранее прописывается в договоре.'], ['Можно взять на несколько часов, а не на смену?', 'Да, для малых катков возможна почасовая аренда или короткий выезд под ямочный ремонт. По тяжёлым машинам обычно выгоднее смена — посчитаем оба варианта под ваш объём.'], ['Какие документы предоставляете?', 'Договор аренды, счёт, акты, при необходимости — путевые листы и данные для пропусков. Работаем по безналу с юрлицами и ИП, с НДС.']]},
  {'slug': 'frontalnye-pogruzchiki', 'name_nom': 'Фронтальные погрузчики', 'name_single': 'Фронтальный погрузчик', 'h1': 'Аренда фронтального погрузчика', 'lead': 'Находим и подаём фронтальный погрузчик под вашу задачу через проверенную партнёрскую сеть КРАН365. Отвечаем за подачу в срок и исправность техники по договору.', 'intro': 'Фронтальный погрузчик нужен для погрузки и перемещения сыпучих и навалочных грузов — щебня, песка, грунта, снега, зерна. Работает на карьерах, складах, стройплощадках и при благоустройстве территории. Ковш быстро меняется на вилы, отвал или челюстной захват под конкретную работу. Подберём машину нужной грузоподъёмности — от 3 до 5+ тонн.', 'price_from': 12000, 'items': [{'subslug': 'xcmg-lw300', 'name': 'Фронтальный погрузчик XCMG LW300 (3 т)', 'specs': ['Грузоподъёмность 3 т', 'Объём ковша 1.8 м³', 'Двигатель 92 кВт'], 'price': 12000}, {'subslug': 'sdlg-lg936', 'name': 'Фронтальный погрузчик SDLG LG936 (3 т)', 'specs': ['Грузоподъёмность 3 т', 'Объём ковша 1.8 м³', 'Полный привод 4×4'], 'price': 12500}, {'subslug': 'xcmg-lw500', 'name': 'Фронтальный погрузчик XCMG LW500 (5 т)', 'specs': ['Грузоподъёмность 5 т', 'Объём ковша 3 м³', 'Двигатель 162 кВт'], 'price': 16000}, {'subslug': 'sdlg-lg958', 'name': 'Фронтальный погрузчик SDLG LG958 (5 т)', 'specs': ['Грузоподъёмность 5 т', 'Объём ковша 3 м³', 'Высота разгрузки 3.1 м'], 'price': 16500}, {'subslug': 'amkodor-333', 'name': 'Фронтальный погрузчик Амкодор 333В (3.4 т)', 'specs': ['Грузоподъёмность 3.4 т', 'Объём ковша 1.9 м³', 'Дизель Д-260'], 'price': 13000}, {'subslug': 'liugong-clg835', 'name': 'Фронтальный погрузчик LiuGong CLG835 (3 т)', 'specs': ['Грузоподъёмность 3 т', 'Объём ковша 1.8 м³', 'Гидромеханическая трансмиссия'], 'price': 12500}, {'subslug': 'liugong-clg856', 'name': 'Фронтальный погрузчик LiuGong CLG856 (5 т)', 'specs': ['Грузоподъёмность 5 т', 'Объём ковша 3 м³', 'Эксплуатационная масса 17 т'], 'price': 16000}, {'subslug': 'pogruzchik-vily', 'name': 'Фронтальный погрузчик с вилами (перевалка)', 'specs': ['Вилы вместо ковша', 'Грузоподъёмность до 5 т', 'Паллеты, трубы, пакетированный груз'], 'price': None}], 'faqs': [['Как быстро подадите погрузчик?', 'Обычно в течение 1–2 суток после заявки, по Москве и области нередко в день обращения. Точный срок подтверждаем при бронировании и фиксируем в договоре.'], ['Оператор входит в стоимость?', 'Да, техника подаётся с опытным машинистом. Аренду без оператора мы не предоставляем — это ответственность за технику и безопасность на объекте.'], ['Какие документы вы даёте?', 'Договор аренды, счёт, акты выполненных работ и УПД. Работаем по безналу с юрлицами и ИП, с НДС и без.'], ['Какой минимальный срок аренды?', 'Стандартная единица — смена 8 часов. На длительные проекты действуют пониженные ставки, считаем индивидуально под объём.'], ['Топливо и доставка входят в цену?', 'Обычно доставка тралом и ГСМ считаются отдельно от ставки за смену. Всё согласуем и пропишем в договоре до начала работ, без сюрпризов.']]},
  {'slug': 'teleskopicheskie-pogruzchiki', 'name_nom': 'Телескопические погрузчики', 'name_single': 'Телескопический погрузчик', 'h1': 'Аренда телескопического погрузчика', 'lead': 'Подберём и подадим телескопический погрузчик (телехендлер) нужной высоты и грузоподъёмности из проверенной сети КРАН365. Отвечаем за сроки подачи и техническое состояние по договору.', 'intro': 'Телескопический погрузчик поднимает и подаёт груз на высоту за счёт выдвижной стрелы — там, где не заедет автокран и не достанет фронтальник. Незаменим на стройке для подачи материалов на этажи, в сельском хозяйстве, на складах и в ангарах. Сменное оборудование — вилы, ковш, крюк, люлька — расширяет применение под задачу. Высота подъёма от 6 до 17+ метров.', 'price_from': 14000, 'items': [{'subslug': 'jcb-531-70', 'name': 'Телескопический погрузчик JCB 531-70 (3.1 т / 7 м)', 'specs': ['Грузоподъёмность 3.1 т', 'Высота подъёма 7 м', 'Полный привод'], 'price': 14000}, {'subslug': 'jcb-535-95', 'name': 'Телескопический погрузчик JCB 535-95 (3.5 т / 9.5 м)', 'specs': ['Грузоподъёмность 3.5 т', 'Высота подъёма 9.5 м', 'Три режима рулевого управления'], 'price': 16000}, {'subslug': 'manitou-mt1440', 'name': 'Телескопический погрузчик Manitou MT 1440 (4 т / 14 м)', 'specs': ['Грузоподъёмность 4 т', 'Высота подъёма 14 м', 'Выдвижные стабилизаторы'], 'price': 19000}, {'subslug': 'manitou-mt625', 'name': 'Телескопический погрузчик Manitou MT 625 (2.5 т / 6 м)', 'specs': ['Грузоподъёмность 2.5 т', 'Высота подъёма 5.9 м', 'Компактный габарит для стеснённых условий'], 'price': 13000}, {'subslug': 'dieci-agri', 'name': 'Телескопический погрузчик Dieci Agri Farmer (3.5 т / 7 м)', 'specs': ['Грузоподъёмность 3.5 т', 'Высота подъёма 7 м', 'Комплектация под АПК'], 'price': 15000}, {'subslug': 'bobcat-t35', 'name': 'Телескопический погрузчик Bobcat T35.130 (3.5 т / 13 м)', 'specs': ['Грузоподъёмность 3.5 т', 'Высота подъёма 13 м', 'Выдвижные опоры'], 'price': 18000}, {'subslug': 'merlo-roto', 'name': 'Телескопический погрузчик Merlo Roto (поворотная башня, 17 м)', 'specs': ['Поворот стрелы 360°', 'Высота подъёма 17 м', 'Грузоподъёмность 4 т'], 'price': None}, {'subslug': 'telehandler-lyulka', 'name': 'Телехендлер с рабочей люлькой', 'specs': ['Рабочая платформа для высотных работ', 'Высота до 14 м', 'Монтаж и обслуживание на высоте'], 'price': None}], 'faqs': [['Чем телескопический погрузчик лучше автокрана?', 'Он мобильнее и проходимее на бездорожье, быстро меняет оснастку и работает в стеснённых условиях. Для точечного подъёма тяжёлых грузов на большую высоту всё же нужен кран — подскажем, что подойдёт под задачу.'], ['Можно ли взять с люлькой для работы на высоте?', 'Да, подаём телехендлер с рабочей платформой для высотных работ. Согласуем оснастку и условия под ваш объект.'], ['Оператор и документы?', 'Техника подаётся с опытным машинистом. Предоставляем договор, счёт, акты и УПД, работаем по безналу с юрлицами и ИП.'], ['Какую высоту выбрать?', 'Ориентируйтесь на реальную высоту подачи плюс запас. Назовите задачу и вес груза — поможем подобрать модель по высоте и грузоподъёмности.'], ['Как быстро подача?', 'По Москве и области обычно 1–2 суток, срочные заявки стараемся закрыть в день обращения. Точный срок подтверждаем при бронировании.']]},
  {'slug': 'mini-pogruzchiki', 'name_nom': 'Мини-погрузчики', 'name_single': 'Мини-погрузчик', 'h1': 'Аренда мини-погрузчика', 'lead': 'Найдём и подадим мини-погрузчик (бобкэт) под ваш объект через проверенную сеть КРАН365. Отвечаем за подачу в срок и исправность техники по договору.', 'intro': 'Мини-погрузчик с бортовым поворотом (skid-steer) манёвренный и проходит там, где крупная техника не развернётся — во дворах, внутри цехов, на узких площадках. Работает с широким набором навесного: ковш, отвал, щётка, гидромолот, бур, вилы. Применяется для уборки территории и снега, планировки, погрузки и лёгкого демонтажа. Компактный, но производительный помощник на малых и средних объёмах.', 'price_from': 10000, 'items': [{'subslug': 'bobcat-s175', 'name': 'Мини-погрузчик Bobcat S175', 'specs': ['Грузоподъёмность 0.8 т', 'Объём ковша 0.4 м³', 'Ширина корпуса 1.8 м'], 'price': 11000}, {'subslug': 'bobcat-s650', 'name': 'Мини-погрузчик Bobcat S650', 'specs': ['Грузоподъёмность 1.3 т', 'Мощность 74 л.с.', 'Быстросъёмная навеска'], 'price': 13000}, {'subslug': 'mksm-800', 'name': 'Мини-погрузчик МКСМ-800', 'specs': ['Грузоподъёмность 0.8 т', 'Отечественная техника', 'Простой ремонт и запчасти'], 'price': 10000}, {'subslug': 'cat-236', 'name': 'Мини-погрузчик Caterpillar 236', 'specs': ['Грузоподъёмность 0.9 т', 'Мощность 74 л.с.', 'Джойстиковое управление'], 'price': 13000}, {'subslug': 'ant-750', 'name': 'Мини-погрузчик ANT 750', 'specs': ['Грузоподъёмность 0.75 т', 'Компактный габарит', 'Бюджетный вариант'], 'price': 10000}, {'subslug': 'locust-l853', 'name': 'Мини-погрузчик Locust L853', 'specs': ['Грузоподъёмность 0.85 т', 'Объём ковша 0.5 м³', 'Вылет для загрузки самосвала'], 'price': 11500}, {'subslug': 'minipogruzchik-gidromolot', 'name': 'Мини-погрузчик с гидромолотом', 'specs': ['Навесной гидромолот', 'Демонтаж и рыхление', 'Работа в стеснённых условиях'], 'price': None}, {'subslug': 'minipogruzchik-shchetka', 'name': 'Мини-погрузчик со щёткой/отвалом', 'specs': ['Сменная щётка и отвал', 'Уборка и снегоочистка', 'Обслуживание территории'], 'price': None}], 'faqs': [['Пройдёт ли в узкие ворота и внутри здания?', 'Да, ширина корпуса от 1.5–1.8 м и разворот на месте позволяют работать в проездах и цехах. Назовите габариты проезда — подберём машину, которая точно зайдёт.'], ['Какое навесное оборудование доступно?', 'Ковш, отвал, щётка, гидромолот, бур, вилы и захваты. Уточните задачу — подадим технику с нужной оснасткой.'], ['С оператором или без?', 'Подаём с опытным оператором. Аренду «голой» техники без машиниста не предоставляем — так надёжнее и для объекта, и для машины.'], ['Документы и оплата?', 'Договор, счёт, акты и УПД. Работаем по безналу с юрлицами и ИП, с НДС и без.'], ['Минимальный заказ и подача?', 'Минимум — смена. По Москве и области подача обычно в течение суток. Доставка тралом считается отдельно и фиксируется в договоре.']]},
  {'slug': 'avtobetononasosy', 'name_nom': 'Автобетононасосы', 'name_single': 'Автобетононасос', 'h1': 'Аренда автобетононасоса в Москве и области', 'lead': 'Автобетононасосы со стрелой от 24 до 52 метров и подачей до 160 м³/ч — от 18 000 ₽ за смену. Своего парка у нас нет: находим и подаём машину нужной длины стрелы через проверенную партнёрскую сеть, оператор в стоимости.', 'intro': 'Автобетононасос подаёт готовую смесь по стреле-трубопроводу точно в опалубку — на высоту, через препятствия и туда, куда не подъедет миксер. Применяют на монолитных фундаментах, перекрытиях, колоннах, стяжках и площадных заливках, где важны скорость и непрерывность бетонирования. Размер подбирают по высоте и дальности подачи: чем длиннее стрела, тем выше и дальше достаёт машина. На малые объёмы берут пумимиксер (насос и барабан в одной машине), на стеснённые условия — прицепной насос с подачей по трубам.', 'price_from': 18000, 'items': [{'subslug': '24-metra', 'name': 'Автобетононасос 24 м', 'specs': ['стрела 24 м', 'подача ~90 м³/ч', 'частные дома и малые объекты'], 'price': 22000}, {'subslug': '28-metrov', 'name': 'Автобетононасос 28 м', 'specs': ['стрела 28 м', '5-секционная стрела', 'коттеджи, перекрытия'], 'price': 24000}, {'subslug': '32-metra', 'name': 'Автобетононасос 32 м', 'specs': ['стрела 32 м', 'вылет ~28 м', 'самый ходовой размер'], 'price': 27000}, {'subslug': '37-metrov', 'name': 'Автобетононасос 37 м', 'specs': ['стрела 37 м', 'подача до 160 м³/ч', 'многоэтажный монолит'], 'price': 33000}, {'subslug': '42-metra', 'name': 'Автобетононасос 42 м', 'specs': ['стрела 42 м', '5 секций', 'высотные и площадные заливки'], 'price': 40000}, {'subslug': '47-52-metra', 'name': 'Автобетононасос 47–52 м', 'specs': ['стрела 47–52 м', 'высотное строительство', 'редкая техника'], 'price': None}, {'subslug': 'pricepnoy-stacionarnyy', 'name': 'Прицепной (стационарный) бетононасос', 'specs': ['без стрелы, по трубопроводу', 'подача на большую высоту и дальность', 'для стеснённых условий'], 'price': 18000}, {'subslug': 'pumi-mikser', 'name': 'Автобетононасос-миксер (пумимиксер)', 'specs': ['стрела + барабан 4–7 м³', 'насос и миксер в одной машине', 'малые объёмы без отдельного миксера'], 'price': 26000}], 'faqs': [['Как считается стоимость аренды бетононасоса?', 'Ориентир — за смену, но чаще цена складывается из подачи машины, отработанного времени (или объёма перекачанного бетона) и переработки сверх смены. Точную стоимость называем под ваш объём, высоту и адрес — расчёт бесплатный.'], ['Оператор входит в стоимость?', 'Да. Машина подаётся с опытным машинистом-оператором, топливо тоже в стоимости. Отдельно оплачивается только подача до объекта и переработка сверх смены.'], ['Как быстро подадите и нужно ли бронировать заранее?', 'Бетононасос обычно резервируют под дату заливки за 1–2 дня, чтобы подать машину точно к началу работ. Срочную подачу в день обращения уточняйте по телефону — при наличии свободной техники организуем.'], ['Можете организовать сам бетон?', 'Да. Подберём бетон нужной марки и объёма с проверенного завода и согласуем время подачи, либо работаем с вашим бетоном. Заранее сообщите марку, объём и график заливки.'], ['Какие документы оформляете?', 'Работаем с физлицами и юрлицами: договор, счёт, акты и закрывающие документы, НДС и ЭДО. Все условия фиксируем в договоре до выезда техники.']]},
  {'slug': 'avtobetonosmesiteli', 'name_nom': 'Автобетоносмесители (миксеры)', 'name_single': 'Автобетоносмеситель (миксер)', 'h1': 'Аренда автобетоносмесителя (миксера) в Москве и области', 'lead': 'Миксеры с барабаном от 2 до 12 м³ — от 13 000 ₽ за смену. Бетон и машины подаём через проверенную сеть заводов и перевозчиков: подберём объём и марку, организуем непрерывную подачу и отвечаем за сроки по договору.', 'intro': 'Автобетоносмеситель (миксер) доставляет готовый бетон с завода на объект и постоянно вращает барабан, чтобы смесь не расслаивалась и не схватывалась в пути. Объём барабана подбирают под задачу: мини-миксеры проезжают в узкие дворы и на дачи, машины на 8–12 м³ везут крупные заливки за меньшее число рейсов. При больших объёмах миксеры ставят «в цепочку», чтобы заливка шла без простоя. Стоимость доставки обычно считают за кубометр бетона и плечо перевозки, аренду самой машины — за смену или рейс.', 'price_from': 13000, 'items': [{'subslug': 'mini-2-4-m3', 'name': 'Мини-миксер 2–4 м³', 'specs': ['барабан 2–4 м³', 'на узком шасси', 'для тесных дворов и дач'], 'price': 13000}, {'subslug': '5-m3', 'name': 'Миксер 5 м³', 'specs': ['барабан 5 м³', 'база КамАЗ', 'малые заливки'], 'price': 15000}, {'subslug': '6-m3', 'name': 'Миксер 6 м³', 'specs': ['барабан 6 м³', 'манёвренный в городе', 'ходовой объём'], 'price': 16000}, {'subslug': '7-m3', 'name': 'Миксер 7 м³', 'specs': ['барабан 7 м³', 'оптимум цена/объём', 'перекрытия, стяжки'], 'price': 17000}, {'subslug': '8-m3', 'name': 'Миксер 8 м³', 'specs': ['барабан 8 м³', '3-осное шасси', 'фундаменты, плиты'], 'price': 18000}, {'subslug': '9-m3', 'name': 'Миксер 9 м³', 'specs': ['барабан 9 м³', 'крупные заливки', 'меньше рейсов'], 'price': 19000}, {'subslug': '10-m3', 'name': 'Миксер 10 м³', 'specs': ['барабан 10 м³', '4-осное шасси', 'большой объём за рейс'], 'price': 21000}, {'subslug': '12-m3', 'name': 'Миксер 12 м³', 'specs': ['барабан 12 м³', 'тяжёлое шасси', 'промышленные объёмы'], 'price': 24000}], 'faqs': [['За что платят — за смену, рейс или кубометр?', 'Доставку готового бетона обычно считают за кубометр плюс плечо перевозки, а аренду самого миксера — за смену или рейс. Что выгоднее под ваш объём и адрес, подскажем при расчёте.'], ['Водитель входит в стоимость?', 'Да, миксер подаётся с водителем, топливо в стоимости. Дополнительно оплачивается только плечо доставки и сверхнормативный простой под разгрузкой.'], ['Можете привезти бетон нужной марки?', 'Да. Организуем бетон с проверенного завода — согласуем марку (например, М200–М350), объём и время подачи, при необходимости с паспортом качества.'], ['Как организовать непрерывную подачу на большой объём?', 'При крупных заливках ставим несколько миксеров «в цепочку» по графику, чтобы бетон поступал без пауз и не простаивали бетононасос или бригада.'], ['Какие документы дадите?', 'Договор, счёт, закрывающие документы, паспорт качества на бетон, работа с НДС и по ЭДО — для физлиц и организаций.']]},
  {'slug': 'yamobury', 'name_nom': 'Ямобуры и буровые', 'name_single': 'Ямобур', 'h1': 'Аренда ямобура в Москве и области', 'lead': 'Ямобуры со шнеками от 250 до 800 мм и глубиной бурения до 8–10 метров — от 10 000 ₽ за смену. Находим и подаём машину нужного диаметра из проверенной партнёрской сети, оператор — в стоимости.', 'intro': 'Ямобур (бурильно-крановая машина) быстро бурит ямы под столбы, опоры освещения и ЛЭП, заборы, ворота, рекламные конструкции и сваи — там, где ручная копка заняла бы дни. Машину подбирают по диаметру шнека и глубине бурения, а также по проходимости: на тракторе МТЗ — по бездорожью, на КамАЗе — на большую глубину и в плотный грунт. Отдельные модели с крановым манипулятором бурят и сразу устанавливают опору за один заезд. Для буронабивных свай и сложного грунта берут буровую установку.', 'price_from': 10000, 'items': [{'subslug': 'na-mtz', 'name': 'Ямобур на МТЗ (БКМ на тракторе)', 'specs': ['база трактор МТЗ-82', 'шнеки 250–500 мм', 'высокая проходимость'], 'price': 12000}, {'subslug': 'na-gaz', 'name': 'Ямобур на ГАЗ', 'specs': ['база ГАЗ (ГАЗон/Садко)', 'глубина до 3 м', 'манёвренный для города'], 'price': 14000}, {'subslug': 'na-kamaz', 'name': 'Ямобур на КамАЗ (тяжёлый)', 'specs': ['база КамАЗ', 'глубина до 8–10 м', 'плотный и мёрзлый грунт'], 'price': 18000}, {'subslug': 'bkm-manipulyator', 'name': 'БКМ-манипулятор (бур + монтаж опор)', 'specs': ['бурит и ставит опору за заезд', 'крановая установка', 'ЛЭП, освещение, заборы'], 'price': 17000}, {'subslug': 'dlya-svai', 'name': 'Ямобур для свай (буронабивные)', 'specs': ['диаметр до 600–800 мм', 'буронабивные сваи', 'свайные фундаменты'], 'price': 20000}, {'subslug': 'malogabaritnyy', 'name': 'Малогабаритный ямобур', 'specs': ['на мини-технике / самоходный', 'проходит в узкие проезды', 'теплицы, дачи, дворы'], 'price': 10000}, {'subslug': 'burovaya-ustanovka', 'name': 'Буровая установка', 'specs': ['большая глубина и диаметр', 'сложный грунт и скала', 'редкая техника'], 'price': None}], 'faqs': [['Как считается аренда ямобура — за смену или за количество ям?', 'Чаще всего за смену с оператором и топливом; на небольших объёмах возможен расчёт за количество пробуренных ям. Точный вариант подберём под вашу задачу и адрес.'], ['Оператор входит в стоимость?', 'Да, машина подаётся с оператором. Отдельно оплачивается только подача до объекта и переработка сверх смены.'], ['Какой диаметр и глубину бурите?', 'Сменными шнеками бурим от 250 до 800 мм, глубина от 1,5 до 8–10 м в зависимости от машины и грунта. Подберём диаметр и глубину под столбы, опоры или сваи — сообщите задачу.'], ['Пробурит ли ямобур мёрзлый или каменистый грунт?', 'Плотный и мёрзлый грунт берёт тяжёлая машина на базе КамАЗ; при камнях и скальных включениях подаём буровую установку. Предупредите о характере грунта заранее — подберём подходящую технику.'], ['Можно сразу установить столбы или опоры?', 'Да. БКМ с крановым манипулятором бурит яму и устанавливает опору, столб или сваю за один заезд. Документы — договор, счёт, НДС и ЭДО для физлиц и юрлиц.']]},
  {'slug': 'vilochnye-pogruzchiki', 'name_nom': 'Вилочные погрузчики', 'name_single': 'Вилочный погрузчик', 'h1': 'Аренда вилочных погрузчиков', 'lead': 'Вилочные погрузчики грузоподъёмностью от 1,5 до 5 тонн с высотой подъёма до 11 метров — от 2 800 ₽ за смену. Находим и подаём машину нужного класса: дизель, газ или электро для работы в закрытом помещении.', 'intro': 'Вилочные погрузчики нужны для разгрузки фур, перемещения поддонов, штабелирования на складе и подачи материалов на стройке. Электрические и газовые модели работают в закрытых помещениях без выхлопа, дизельные и внедорожные — на открытых площадках и грунте. Подбираем машину по весу груза, высоте подъёма и условиям работы.', 'price_from': 2800, 'items': [{'subslug': 'shtabeler-15t', 'name': 'Самоходный штабелёр 1.5 т', 'specs': ['Грузоподъёмность 1.5 т', 'Подъём до 3.5 м, компактный', 'Разгрузка и штабелирование в складе'], 'price': 2800}, {'subslug': 'toyota-8fg15', 'name': 'Toyota 8FG15 (газ/бензин 1.5 т)', 'specs': ['Грузоподъёмность 1.5 т', 'Высота подъёма до 3 м', 'Склады, разгрузка фур'], 'price': 3500}, {'subslug': 'elektro-2t', 'name': 'Электропогрузчик Hangcha 2 т', 'specs': ['Грузоподъёмность 2 т', 'Электро, без выхлопа — для помещений', 'Работа в закрытых складах'], 'price': 3800}, {'subslug': 'richtrak-15t', 'name': 'Ричтрак 1.5 т', 'specs': ['Грузоподъёмность 1.5 т', 'Подъём до 8–11 м', 'Узкие проходы, высокие стеллажи'], 'price': 4500}, {'subslug': 'komatsu-fd30', 'name': 'Komatsu FD30 (дизель 3 т)', 'specs': ['Грузоподъёмность 3 т', 'Высота подъёма до 4.5 м', 'Открытые площадки, стройка'], 'price': 4500}, {'subslug': 'vnedorozhnyy-35t', 'name': 'Внедорожный погрузчик 3.5 т', 'specs': ['Грузоподъёмность 3.5 т', 'Повышенная проходимость, пневмошины', 'Грунт, бездорожье, стройплощадка'], 'price': 5500}, {'subslug': 'toyota-5t', 'name': 'Toyota (дизель 5 т)', 'specs': ['Грузоподъёмность 5 т', 'Усиленная мачта', 'Тяжёлые поддоны, металл, ЖБИ'], 'price': 6500}], 'faqs': [['Погрузчик подаёте с оператором?', 'Обычно да — с опытным водителем-погрузчиком в смену. Если у вас есть сотрудник с удостоверением, возможна подача без оператора.'], ['Как быстро подадите технику?', 'По Москве, как правило, в течение дня; на срочные задачи — от 2–4 часов при наличии свободной машины в сети.'], ['Что взять для склада — электро или дизель?', 'В закрытых помещениях только электрический или газовый: нет выхлопа. Дизель подаём на открытые площадки и стройку.'], ['Какой минимальный срок аренды?', 'Стандартная смена — 8 часов. На короткие задачи есть почасовая подача, уточняйте при заявке.'], ['Какие документы дадите?', 'Договор аренды, счёт, УПД. Работаем по безналу, с НДС и без — под ваш вариант учёта.']]},
  {'slug': 'gusenichnye-ekskavatory', 'name_nom': 'Гусеничные экскаваторы', 'name_single': 'Гусеничный экскаватор', 'h1': 'Аренда гусеничных экскаваторов', 'lead': 'Гусеничные экскаваторы массой от 20 до 36 тонн с ковшом 0,9–1,8 м³ и глубиной копания до 7,5 метра — от 18 000 ₽ за смену. Подберём машину под ваш объём земляных работ из проверенной сети партнёров и организуем доставку тралом.', 'intro': 'Большие гусеничные экскаваторы массой 20–36 т применяют для разработки котлованов и траншей, планировки, погрузки грунта и работы в карьерах. Гусеничный ход даёт устойчивость на слабых и неровных грунтах, а с навесным гидромолотом машина сносит бетон и разрушает скалу. Подбираем массу, вылет и объём ковша под ваш объект и тип грунта.', 'price_from': 18000, 'items': [{'subslug': 'komatsu-pc200', 'name': 'Komatsu PC200 (20 т)', 'specs': ['Масса ~20 т, ковш ~1.0 м³', 'Глубина копания до 6.6 м', 'Котлованы, траншеи, планировка'], 'price': 18000}, {'subslug': 'hitachi-zx200', 'name': 'Hitachi ZX200 (20 т)', 'specs': ['Масса ~20 т, ковш ~0.9 м³', 'Глубина копания до 6.7 м', 'Универсальные земляные работы'], 'price': 18000}, {'subslug': 'cat-320', 'name': 'Caterpillar 320 (22 т)', 'specs': ['Масса ~22 т, ковш ~1.2 м³', 'Глубина копания до 6.7 м', 'Разработка грунта, погрузка в самосвал'], 'price': 19000}, {'subslug': 'hyundai-r300', 'name': 'Hyundai R300 (30 т)', 'specs': ['Масса ~30 т, ковш ~1.4 м³', 'Глубина копания до 7.3 м', 'Земляные работы большого объёма'], 'price': 23000}, {'subslug': 'doosan-dx300', 'name': 'Develon (Doosan) DX300 (30 т)', 'specs': ['Масса ~30 т, ковш ~1.4 м³', 'Глубина копания до 7.4 м', 'Большие объёмы, карьер'], 'price': 24000}, {'subslug': 'komatsu-pc300', 'name': 'Komatsu PC300 (30 т)', 'specs': ['Масса ~30 т, ковш ~1.5 м³', 'Глубина копания до 7.5 м', 'Карьеры, крупные котлованы'], 'price': 25000}, {'subslug': 'cat-336', 'name': 'Caterpillar 336 (36 т)', 'specs': ['Масса ~36 т, ковш ~1.8 м³', 'Усиленная рама, высокая производительность', 'Тяжёлые грунты, скальник'], 'price': None}, {'subslug': 's-gidromolotom', 'name': 'Экскаватор с гидромолотом 20–30 т', 'specs': ['База 20–30 т + навесной гидромолот', 'Дробление бетона и скалы', 'Снос и демонтаж фундаментов'], 'price': None}], 'faqs': [['Кто занимается доставкой на объект?', 'Организуем перевозку тралом до площадки. Стоимость доставки считаем отдельно по расстоянию и массе машины.'], ['Экскаватор с машинистом?', 'Да, опытный машинист входит в смену. Вопрос по ГСМ решаем в договоре — за наш счёт или заказчика.'], ['Можно с гидромолотом для сноса?', 'Да, подберём базу нужной массы с навесным гидромолотом под демонтаж, дробление бетона или скального грунта.'], ['Какая минимальная смена?', 'Обычно 8–10 часов. На большие объёмы согласуем сменный или вахтовый график с фиксацией выработки.'], ['Какие документы предоставляете?', 'Договор аренды спецтехники, счёт, УПД и путевые/сменные рапорты. Работаем по безналу.']]},
  {'slug': 'bortovye-dlinnomery', 'name_nom': 'Бортовые длинномеры', 'name_single': 'Бортовой длинномер', 'h1': 'Аренда бортовых длинномеров', 'lead': 'Бортовые длинномеры с платформой от 8 до 13,6 метра и грузоподъёмностью от 5 до 20 тонн — от 8 000 ₽ за смену. Организуем подачу под ваш груз и маршрут через проверенных перевозчиков, отвечаем за сроки по договору.', 'intro': 'Бортовые длинномеры перевозят металлопрокат, трубы, пиломатериалы, плиты, ЖБИ и длинномерный груз до 13.6 м. Открытая платформа с кониками удобна для боковой и верхней погрузки краном или манипулятором, а вариант с КМУ грузит себя сам. Подбираем тоннаж и длину платформы под конкретный груз и маршрут — по городу и межгород.', 'price_from': 8000, 'items': [{'subslug': 'srednetonnazh-8m', 'name': 'Среднетоннажник борт 5–8 т, 8 м', 'specs': ['Грузоподъёмность 5–8 т', 'Длина платформы 7–8 м', 'Городская доставка, узкие подъезды'], 'price': 8000}, {'subslug': 'kamaz-12t', 'name': 'КамАЗ длинномер 12 т, 12 м', 'specs': ['Грузоподъёмность 10–12 т', 'Длина платформы ~12 м', 'Стройматериалы, трубы, металл'], 'price': 11000}, {'subslug': 'bort-20t-136', 'name': 'Бортовой 20 т, 13.6 м (MAN/Volvo)', 'specs': ['Грузоподъёмность 20 т', 'Длина платформы 13.6 м', 'Коники, крепление ремнями и стропами'], 'price': 14000}, {'subslug': 'scania-20t', 'name': 'Scania борт 20 т, 13.6 м', 'specs': ['Грузоподъёмность 20 т', 'Ровный пол, платформа 13.6 м', 'Межгород, доставка по России'], 'price': 14000}, {'subslug': 'bort-tent-20t', 'name': 'Борт с тентом 20 т, 13.6 м', 'specs': ['Грузоподъёмность 20 т, тент/каркас', 'Защита груза от осадков', 'Сборные и штучные грузы'], 'price': 15000}, {'subslug': 's-manipulyatorom', 'name': 'Длинномер с манипулятором (КМУ)', 'specs': ['Борт 12–15 т + КМУ 5–7 т', 'Самопогрузка без крана', 'Плиты, срубы, спецтехника'], 'price': 16000}, {'subslug': 'negabarit-udlinennyy', 'name': 'Длинномер под негабарит', 'specs': ['Удлинённая платформа под длинномер', 'Балки, сваи, фермы, опоры', 'Пропуска и сопровождение'], 'price': None}], 'faqs': [['Как считается стоимость аренды?', 'По Москве — за смену, межгород — за километр по маршруту. Рассчитаем точную стоимость под ваш адрес и груз.'], ['Погрузка входит в услугу?', 'Вариант с манипулятором грузит себя сам. Для обычного борта погрузку организуете вы краном или погрузчиком, либо подадим машину с КМУ.'], ['Чем крепится груз?', 'Коники, стяжные ремни, стойки и цепи. Поможем правильно раскрепить длинномер по правилам перевозки.'], ['Возите негабарит?', 'Да, подадим удлинённую платформу и оформим пропуска и сопровождение. Негабарит считаем отдельно по параметрам груза.'], ['Какие документы оформляете?', 'Договор, транспортную накладную, счёт и УПД. Работаем по безналу с юрлицами и ИП.']]},
  {'slug': 'pnevmokolesnye-krany', 'name_nom': 'Пневмоколёсные краны', 'name_single': 'Пневмоколёсный кран', 'h1': 'Аренда пневмоколёсного крана', 'lead': 'Пневмоколёсные краны грузоподъёмностью от 16 до 100 тонн со стрелой до 50 метров — от 25 000 ₽ за смену. Подберём и подадим машину из проверенной партнёрской сети, с машинистом и документами.', 'intro': 'Пневмоколёсный кран — самоходный стреловой кран на специальном многоосном пневмоколёсном шасси. В отличие от автокрана он рассчитан на низкую скорость и повышенную устойчивость: работает на выносных опорах, а часть моделей может перемещаться с грузом в пределах площадки. Применяют на промышленных объектах, складах, монтаже оборудования и ЖБИ, где важны устойчивость и грузоподъёмность, а не скорость передвижения по дорогам общего пользования.', 'price_from': 25000, 'items': [{'subslug': 'pk-16t', 'name': 'Кран 16 т, стрела 18 м', 'specs': ['Грузоподъёмность 16 т', 'Высота подъёма до 18 м', 'Компактный, для стеснённых промплощадок'], 'price': 22000}, {'subslug': 'pk-25t', 'name': 'Кран 25 т, стрела 28 м', 'specs': ['Грузоподъёмность 25 т', 'Стрела до 28 м + гусёк', 'Перемещение с грузом в пределах площадки'], 'price': 28000}, {'subslug': 'pk-36t', 'name': 'Кран 36 т, стрела 32 м', 'specs': ['Грузоподъёмность 36 т', 'Высота подъёма до 32 м', 'Высокая устойчивость на выносных опорах'], 'price': 38000}, {'subslug': 'pk-40t', 'name': 'Кран 40 т, стрела 35 м', 'specs': ['Грузоподъёмность 40 т', 'Стрела до 35 м', 'Поворот 360°, тяжёлые монтажи'], 'price': 45000}, {'subslug': 'pk-50t', 'name': 'Кран 50 т, стрела 40 м', 'specs': ['Грузоподъёмность 50 т', 'Высота подъёма до 40 м', 'Универсал для промышленных объектов'], 'price': 58000}, {'subslug': 'pk-63t', 'name': 'Кран 63 т, стрела 42 м', 'specs': ['Грузоподъёмность 63 т', 'Стрела до 42 м + удлинитель', 'Для тяжёлого оборудования и ЖБИ'], 'price': 75000}, {'subslug': 'pk-100t', 'name': 'Кран 100 т, стрела 50 м', 'specs': ['Грузоподъёмность 100 т', 'Высота подъёма до 50 м', 'Подача и цена под запрос'], 'price': None}], 'faqs': [['Чем пневмоколёсный кран отличается от автокрана?', 'У автокрана крановая установка стоит на серийном грузовом шасси, и он быстро едет по дорогам. Пневмоколёсный кран собран на специальном низкоскоростном многоосном шасси: он устойчивее при работе и часть моделей может перемещаться с грузом в пределах площадки, но на объект его перегоняют на небольшой скорости или везут тралом.'], ['Как подобрать грузоподъёмность?', 'Считаем не только вес груза, но и вылет — расстояние от оси крана до точки установки. На большом вылете доступная грузоподъёмность резко падает, поэтому подбираем по грузовысотной характеристике под ваш вес, вылет и высоту. Пришлите вес, габариты груза и схему площадки — подберём с запасом.'], ['Кран приедет с оператором?', 'Да, подаём только с аттестованным машинистом крана и всеми документами на технику. Стропальщиков и такелаж считаем отдельно и поможем организовать при необходимости.'], ['Нужны ли выносные опоры?', 'Для номинальной грузоподъёмности — да: кран работает на выдвинутых аутригерах, под них нужна ровная площадка с достаточной несущей способностью грунта. Часть моделей берёт ограниченный груз без опор или с частичным выдвижением — уточним под конкретную задачу.'], ['Какие документы даёте на объект?', 'Путевой лист, паспорт и свидетельство на кран, удостоверение и наряд-допуск машиниста, при работе в охранных зонах — схему производства работ (ППР). Договор и закрывающие документы — по стандартной форме для юрлиц и физлиц.']]},
  {'slug': 'vezdehodnye-krany', 'name_nom': 'Вездеходные краны (Rough Terrain)', 'name_single': 'Вездеходный кран (Rough Terrain)', 'h1': 'Аренда вездеходного крана (Rough Terrain)', 'lead': 'Вездеходные краны (Rough Terrain) грузоподъёмностью от 20 до 100 тонн со стрелой до 47 метров — от 35 000 ₽ за смену. Полный привод и поворотные колёса дают проходимость там, где обычный автокран встанет; доставка тралом, оператор в комплекте.', 'intro': 'Вездеходный кран (Rough Terrain, RT) — компактный самоходный кран на полноприводном шасси с большими внедорожными шинами, всеми поворотными колёсами и одной кабиной. Создан для работы внутри стройплощадки: проходит по грунту, снегу и бездорожью, маневрирует в стеснении, включая режим «краб». По дорогам общего пользования практически не передвигается — на объект его доставляют тралом, поэтому он оптимален для работ на одном месте, где обычный автокран не пройдёт.', 'price_from': 35000, 'items': [{'subslug': 'rt-20t', 'name': 'Кран 20 т, стрела 21 м', 'specs': ['Грузоподъёмность 20 т', 'Высота подъёма до 21 м', 'Полный привод, все колёса поворотные'], 'price': 30000}, {'subslug': 'rt-25t', 'name': 'Кран 25 т, стрела 26 м', 'specs': ['Грузоподъёмность 25 т', 'Стрела до 26 м', 'Проходимость по грунту и снегу'], 'price': 35000}, {'subslug': 'rt-35t', 'name': 'Кран 35 т, стрела 30 м', 'specs': ['Грузоподъёмность 35 т', 'Высота подъёма до 30 м', 'Маневр «краб» в стеснённых условиях'], 'price': 45000}, {'subslug': 'rt-50t', 'name': 'Кран 50 т, стрела 35 м', 'specs': ['Грузоподъёмность 50 т', 'Стрела до 35 м + гусёк', 'Одна кабина, компактная база'], 'price': 60000}, {'subslug': 'rt-60t', 'name': 'Кран 60 т, стрела 40 м', 'specs': ['Грузоподъёмность 60 т', 'Высота подъёма до 40 м', 'Для котлованов и бездорожья'], 'price': 72000}, {'subslug': 'rt-80t', 'name': 'Кран 80 т, стрела 43 м', 'specs': ['Грузоподъёмность 80 т', 'Стрела до 43 м', 'Тяжёлые подъёмы прямо на стройплощадке'], 'price': 95000}, {'subslug': 'rt-100t', 'name': 'Кран 100 т, стрела 47 м', 'specs': ['Грузоподъёмность 100 т', 'Высота подъёма до 47 м', 'Доставка тралом, цена под запрос'], 'price': None}], 'faqs': [['Где реально нужен вездеходный кран?', 'Там, где обычный автокран не пройдёт или увязнет: стройплощадки без дорог, грунт, снег, котлованы, стеснённые пятна застройки. Полный привод и все поворотные колёса дают проходимость и маневренность на бездорожье.'], ['Может ли он сам доехать до объекта?', 'По дорогам общего пользования вездеходный кран практически не передвигается — у него низкая скорость и нет допуска для трасс. На объект его доставляют тралом, поэтому в смету закладываем доставку и погрузку-разгрузку.'], ['Чем RT отличается от All Terrain?', 'Вездеходный (Rough Terrain) — компактный, одна кабина, для работы внутри площадки, возится тралом. All Terrain — многоосный, сам едет по трассе на высокой скорости и берёт большие веса. RT дешевле в подаче на короткий объект, AT универсальнее для дальних и тяжёлых работ.'], ['Как заказать подбор?', 'Пришлите вес и габариты груза, вылет, высоту подъёма и фото или схему площадки. Подберём модель из проверенной сети под задачу и посчитаем смену с учётом доставки тралом.'], ['Кран подаётся с оператором и стропами?', 'Машинист входит в подачу всегда. Стропы, траверсы и стропальщиков подбираем под конкретный груз — можем организовать такелаж отдельной позицией.']]},
  {'slug': 'korotkobaznye-gorodskie-krany', 'name_nom': 'Короткобазные городские краны', 'name_single': 'Короткобазный городской кран', 'h1': 'Аренда короткобазного городского крана', 'lead': 'Короткобазные краны грузоподъёмностью от 25 до 50 тонн со стрелой до 42 метров — от 22 000 ₽ за смену. Работают в плотной городской застройке и приходят своим ходом, без трала, с машинистом и полным пакетом документов.', 'intro': 'Короткобазный городской кран — компактный автокран с укороченной колёсной базой и малым радиусом разворота, часто с поднимающейся кабиной для обзора. Главное преимущество — маневренность в плотной городской застройке: заезд в тесные дворы, на паркинги и площадки в центре, где длинный кран не развернётся. При этом он сам передвигается по дорогам общего пользования, что удешевляет подачу без трала и ускоряет выезд по Москве и области.', 'price_from': 22000, 'items': [{'subslug': 'gk-25t', 'name': 'Кран 25 т, стрела 26 м', 'specs': ['Грузоподъёмность 25 т', 'Высота подъёма до 26 м', 'Малый радиус разворота'], 'price': 24000}, {'subslug': 'gk-30t', 'name': 'Кран 30 т, стрела 30 м', 'specs': ['Грузоподъёмность 30 т', 'Стрела до 30 м', 'Заезд в тесные дворы и на паркинги'], 'price': 30000}, {'subslug': 'gk-35t', 'name': 'Кран 35 т, стрела 34 м', 'specs': ['Грузоподъёмность 35 т', 'Высота подъёма до 34 м', 'Поднимающаяся кабина, хороший обзор'], 'price': 35000}, {'subslug': 'gk-40t', 'name': 'Кран 40 т, стрела 36 м', 'specs': ['Грузоподъёмность 40 т', 'Стрела до 36 м + гусёк', 'Ход по дорогам общего пользования'], 'price': 42000}, {'subslug': 'gk-45t', 'name': 'Кран 45 т, стрела 40 м', 'specs': ['Грузоподъёмность 45 т', 'Высота подъёма до 40 м', 'Переменный вылет опор для узких пятен'], 'price': 50000}, {'subslug': 'gk-50t', 'name': 'Кран 50 т, стрела 42 м', 'specs': ['Грузоподъёмность 50 т', 'Стрела до 42 м', 'Максимум грузоподъёмности для города'], 'price': 58000}], 'faqs': [['В чём смысл короткобазного крана?', 'Короткая колёсная база и малый радиус разворота позволяют заезжать в тесные дворы, на паркинги и площадки в центре города, где длинный автокран не развернётся. При этом кран сам едет по дорогам общего пользования, без отдельного трала.'], ['Сколько места нужно для работы?', 'Заметно меньше, чем классическому крану: компактное шасси и выносные опоры с переменным вылетом позволяют встать на ограниченном пятне. Пришлите размеры площадки — проверим установку и вылет до точки монтажа.'], ['Он сам доедет по городу?', 'Да, у короткобазных кранов есть допуск на дороги общего пользования, отдельный трал обычно не нужен — это экономит на подаче в черте города. По Москве и области подаём оперативно.'], ['Подходит для монтажа оборудования на кровлю или в окно?', 'Да, это частый сценарий: подъём оборудования на крышу, монтаж вентиляции и кондиционеров, остекление. Подберём под вес и вылет с учётом препятствий — дайте высоту здания и точку установки.'], ['Оператор и документы включены?', 'Кран подаём с машинистом и полным пакетом документов. Для работ у зданий и в охранных зонах подготовим схему работ; согласование перекрытий и ордера поможем оформить.']]},
  {'slug': 'krany-na-spetsshassi-all-terrain', 'name_nom': 'Краны на спецшасси (All Terrain)', 'name_single': 'Кран на спецшасси (All Terrain)', 'h1': 'Аренда крана на спецшасси (All Terrain)', 'lead': 'Краны на спецшасси грузоподъёмностью от 40 до 500 тонн со стрелой до 70 метров — от 40 000 ₽ за смену. Подберём и подадим машину под тяжёлый или высотный подъём: с ППР, сопровождением и оператором.', 'intro': 'Кран на спецшасси (All Terrain, AT) — самый универсальный тип самоходных кранов: многоосное полноприводное шасси с высокой скоростью по трассе, длинной телескопической стрелой и большим набором противовесов. Берёт от десятков до сотен тонн и работает на больших вылетах и высотах. Лёгкие модели готовы к работе почти сразу, тяжёлым нужны монтаж противовеса и сопровождение на объекте — логистику, подбор и разрешения берём на себя.', 'price_from': 40000, 'items': [{'subslug': 'at-40t', 'name': 'Кран 40 т, стрела 35 м', 'specs': ['Грузоподъёмность 40 т', 'Стрела до 35 м', 'Сам едет по трассе, быстрая подача'], 'price': 40000}, {'subslug': 'at-60t', 'name': 'Кран 60 т, стрела 48 м', 'specs': ['Грузоподъёмность 60 т', 'Высота подъёма до 48 м', 'Готов к работе почти сразу'], 'price': 55000}, {'subslug': 'at-90t', 'name': 'Кран 90-100 т, стрела 50 м', 'specs': ['Грузоподъёмность 90 т', 'Стрела до 50 м + гусёк', 'Универсал для металлоконструкций'], 'price': 90000}, {'subslug': 'at-130t', 'name': 'Кран 130 т, стрела 60 м', 'specs': ['Грузоподъёмность 130 т', 'Высота подъёма до 60 м', 'Длинная телескопическая стрела'], 'price': 120000}, {'subslug': 'at-160t', 'name': 'Кран 160 т, стрела 60 м', 'specs': ['Грузоподъёмность 160 т', 'Стрела до 60 м + удлинители', 'Противовес возят отдельными машинами'], 'price': None}, {'subslug': 'at-250t', 'name': 'Кран 250 т, стрела 70 м', 'specs': ['Грузоподъёмность 250 т', 'Высота подъёма до 80 м', 'Монтаж/демонтаж на объекте, цена под запрос'], 'price': None}, {'subslug': 'at-350t', 'name': 'Кран 350 т, стрела 70 м', 'specs': ['Грузоподъёмность 350 т', 'Стрела до 70 м + гусёк', 'Тяжёлые проектные подъёмы'], 'price': None}, {'subslug': 'at-500t', 'name': 'Кран 500 т, высота свыше 100 м', 'specs': ['Грузоподъёмность 500 т', 'Высота с гуськом свыше 100 м', 'Проект, логистика и цена под запрос'], 'price': None}], 'faqs': [['Когда нужен кран на спецшасси?', 'Для тяжёлых и высотных подъёмов: монтаж металлоконструкций, ферм, ЖБИ, оборудования, работа на большом вылете и высоте. All Terrain берёт от десятков до сотен тонн и сам приезжает по трассе на высокой скорости.'], ['Нужен ли монтаж и демонтаж на объекте?', 'Лёгкие модели готовы к работе почти сразу. Тяжёлым (примерно от 160-250 т) нужны противовесы и иногда удлинители стрелы, которые везут отдельными машинами и собирают на месте — это закладываем во время и стоимость. Логистику сопровождения считаем заранее.'], ['Как формируется цена на большие краны?', 'На тяжёлые AT цена чаще под запрос: она зависит от грузоподъёмности, набора противовеса, длины стрелы и гуська, числа машин сопровождения и дальности. Пришлите задачу — посчитаем смену или проект целиком.'], ['Что нужно для подбора?', 'Вес и габариты груза, вылет (расстояние до точки установки), высота подъёма, условия площадки и подъездов. По грузовысотным характеристикам подберём модель с запасом и проверим проходимость и место под выносные опоры.'], ['Оператор, документы, ППР?', 'Подаём с аттестованным машинистом и документами на кран. Для тяжёлых подъёмов готовим проект производства работ (ППР) и схемы строповки, согласуем допуски — организацию берём на себя.']]},
  {'slug': 'mini-krany-paukoobraznye', 'name_nom': 'Мини-краны (паукообразные)', 'name_single': 'Мини-кран (паукообразный)', 'h1': 'Аренда мини-крана (паукообразного)', 'lead': 'Паукообразные мини-краны грузоподъёмностью от 1 до 10 тонн и шириной от 600 мм — проходят в дверной проём — от 28 000 ₽ за смену. Подберём и подадим машину из собственного парка и проверенной партнёрской сети по Москве и России.', 'intro': 'Паукообразный мини-кран — компактный гусеничный кран с выносными опорами-«лапами», которые раскрываются как у паука и дают устойчивость при малой массе. Проходит в дверной проём и грузовой лифт, работает на готовых полах и в стеснённых условиях, куда не заедет автокран: монтаж стекла и лифтов, работы в цехах, атриумах, подвалах и на кровле. Многие модели идут с двойным приводом (дизель + электро 380 В) — на улице работают на ДВС, в помещении от сети, без выхлопа и с низким шумом. Главное отличие от автокрана — точная работа на минимальной площади и проходимость там, где нет места для стандартной техники.', 'price_from': 28000, 'items': [{'subslug': 'mini-1t', 'name': 'Мини-кран 1 т (класс Maeda MC104)', 'specs': ['Грузоподъёмность до 1 т', 'Высота подъёма до 8 м, вылет до 6 м', 'Ширина в транспорте от 600 мм — проходит в дверь'], 'price': 28000}, {'subslug': 'mini-2t', 'name': 'Мини-кран 2,8 т (класс Maeda MC285 / Jekko SPX)', 'specs': ['Грузоподъёмность до 2,8 т', 'Высота подъёма до 12 м', 'Двойной привод: дизель + электро 380 В'], 'price': 33000}, {'subslug': 'mini-3t', 'name': 'Мини-кран 3 т (класс Maeda MC305 / Hoeflon C10)', 'specs': ['Грузоподъёмность до 3 т', 'Максимальная высота крюка ~14 м', 'Резиновые гусеницы, работа на уклоне'], 'price': 38000}, {'subslug': 'mini-4t', 'name': 'Мини-кран 4 т (класс Maeda MC405 / Jekko SPX532)', 'specs': ['Грузоподъёмность до 3,8–4 т', 'Вылет стрелы до 12 м', 'Радиоуправление, поворот 360°'], 'price': 42000}, {'subslug': 'mini-6t', 'name': 'Мини-кран 6 т (класс Hoeflon C30 / Jekko SPX650)', 'specs': ['Грузоподъёмность до 6 т', 'Высота подъёма до 20 м', 'Съёмный гусёк (jib) для увеличения вылета'], 'price': 50000}, {'subslug': 'mini-8t', 'name': 'Мини-кран 8 т (класс Maeda MC815 / Jekko SPX1275)', 'specs': ['Грузоподъёмность до 8 т', 'Максимальная высота крюка ~19–24 м', 'Электрогидравлика для чистых помещений'], 'price': 58000}, {'subslug': 'mini-10t', 'name': 'Мини-кран 10 т (класс Jekko SPX1280 / Kegiom)', 'specs': ['Грузоподъёмность до 10 т', 'Вылет до 30 м с гуськом', 'Стекломанипулятор / вакуумный захват опционально'], 'price': None}], 'faqs': [['Как подобрать мини-кран под мою задачу?', 'Скажите вес и габарит груза, высоту и вылет (куда и на какое расстояние подать), ширину проёмов и тип пола. По этим данным подберём модель с запасом по грузовому моменту и подадим её на объект.'], ['Кран действительно проедет в помещение?', 'Да. В транспортном положении «лапы» и стрела сложены, ширина от 600 мм — проходит в стандартный дверной проём и в грузовой лифт. На месте опоры раскрываются и распределяют нагрузку на пол.'], ['Не повредит ли гусеничный кран готовый пол?', 'Ставим на резиновые гусеницы и подкладываем распределительные плиты и маты под опоры. Заранее считаем нагрузку на перекрытие — при необходимости ограничиваем вылет или добавляем настил.'], ['Можно ли работать в помещении без выхлопа?', 'Да, берём модели с двойным приводом или электрокраны: на улице — дизель, внутри — питание от сети 380 В, без выхлопных газов и с низким уровнем шума.'], ['Оператор и документы входят?', 'Подаём кран с аттестованным машинистом; предоставляем документы на технику, удостоверение оператора и, при необходимости, ППР для допуска на объект.']]},
  {'slug': 'samomontiruyushchiesya-bashennye-krany', 'name_nom': 'Самомонтирующиеся башенные краны', 'name_single': 'Самомонтирующийся башенный кран', 'h1': 'Аренда самомонтирующегося башенного крана', 'lead': 'Самомонтирующиеся башенные краны грузоподъёмностью от 1,8 до 8 тонн с вылетом стрелы до 55 метров: раскладываются гидравликой, без второго крана. Организуем аренду с доставкой, монтажом и оператором по Москве и области.', 'intro': 'Самомонтирующийся башенный кран разворачивается сам: гидравлика поднимает мачту и раскладывает стрелу за несколько часов, без привлечения второго крана и монтажной бригады. Приезжает на прицепе или собственным ходом, ставится на балластное основание и запитывается от электросети 380 В. Идеален для малоэтажного и коттеджного строительства, где классический башенный кран избыточен и дорог в монтаже. Отличается быстрым пуском в тот же день, малой требуемой площадкой и тихой работой без выхлопа — можно ставить в жилой застройке.', 'price_from': None, 'items': [{'subslug': 'se-igo15', 'name': 'Кран 1,8 т, стрела 24 м (класс Potain Igo 15)', 'specs': ['Грузоподъёмность до 1,8 т', 'Вылет 24 м, на конце ~0,9 т', 'Высота под крюк ~19 м, автомонтаж'], 'price': None}, {'subslug': 'se-igo21', 'name': 'Кран 2,2 т, стрела 30 м (класс Potain Igo 21)', 'specs': ['Грузоподъёмность до 2,2 т', 'Вылет стрелы 30 м', 'Высота под крюк ~21 м, питание 380 В'], 'price': None}, {'subslug': 'se-igo32', 'name': 'Кран 3 т, стрела 32 м (класс Potain Igo 32)', 'specs': ['Грузоподъёмность до 3 т', 'Вылет стрелы 32 м', 'Раскладка гидравликой без второго крана'], 'price': None}, {'subslug': 'se-igo50', 'name': 'Кран 4 т, стрела 40 м (класс Potain Igo 50)', 'specs': ['Грузоподъёмность до 4 т', 'Вылет 40 м, на конце ~1 т', 'Высота под крюк до 25 м'], 'price': None}, {'subslug': 'se-53k', 'name': 'Кран 4 т, стрела 40 м (класс Liebherr 53 K)', 'specs': ['Грузоподъёмность до 4 т', 'Вылет 40 м', 'Подъём стрелы (люффинг) в стеснённых условиях'], 'price': None}, {'subslug': 'se-81k', 'name': 'Кран 6 т, стрела 45 м (класс Liebherr 81 K)', 'specs': ['Грузоподъёмность до 6 т', 'Вылет 45 м, на конце ~1,4 т', 'Высота под крюк до 40,5 м'], 'price': None}, {'subslug': 'se-125k', 'name': 'Кран 8 т, стрела 45–55 м (класс Liebherr 125 K)', 'specs': ['Грузоподъёмность до 8 т', 'Вылет до 55 м', 'Наибольшая высота в классе, автомонтаж'], 'price': None}], 'faqs': [['Чем самомонтирующийся кран лучше классического башенного?', 'Он раскладывается сам за несколько часов — без монтажной бригады и второго крана, требует меньше площади под установку и балласт. Для коттеджей и малоэтажки это экономит и деньги, и время пуска.'], ['Сколько занимает установка и что нужно на площадке?', 'От заезда до готовности к работе — обычно несколько часов в тот же день. Нужны ровная уплотнённая площадка под балласт, подключение к сети 380 В и согласованные зоны работы стрелы.'], ['Какое питание и уровень шума?', 'Работает от электросети 380 В — тихо и без выхлопа, что удобно в жилой застройке. Требуемую мощность и схему подключения подберём под конкретную модель заранее.'], ['Аренда посменно или помесячно?', 'Такой кран берут на объект, поэтому аренда обычно помесячная — с монтажом, демонтажом и доставкой по договору. Точную стоимость посчитаем под ваши сроки, высоту и вылет.'], ['Оператор, документы, регистрация в Ростехнадзоре?', 'Подаём с аттестованным крановщиком и полным пакетом документов на ОПО (ППРк, паспорта, свидетельства). Поможем с постановкой на учёт и допуском на объект.']]},
  {'slug': 'bystromontiruemye-bashennye-krany', 'name_nom': 'Быстромонтируемые башенные краны', 'name_single': 'Быстромонтируемый башенный кран', 'h1': 'Аренда быстромонтируемого башенного крана', 'lead': 'Быстромонтируемые башенные краны грузоподъёмностью от 5 до 12 тонн с вылетом стрелы до 65 метров; монтаж автокраном занимает 1–2 дня. Подберём и подадим кран с наладкой и оператором из проверенной сети подрядчиков по Москве и России.', 'intro': 'Быстромонтируемый башенный кран собирают на объекте из крупных готовых блоков за 1–2 дня с помощью автокрана — быстрее классического, но с большей высотой и грузоподъёмностью, чем у самомонтирующихся. Мачта наращивается секциями (в том числе приставным и самоподъёмным способом), поэтому кран «дотягивается» выше и берёт более тяжёлый груз. Применяется на среднеэтажном строительстве, реконструкции и там, где нужен ощутимый вылет при сжатых сроках монтажа. От самомонтирующегося отличается тем, что даёт заметно больший грузовой момент и высоту под крюк ценой сборки вторым краном.', 'price_from': None, 'items': [{'subslug': 'qe-mct88', 'name': 'Кран 5 т, стрела 52 м (класс Potain MCT 88)', 'specs': ['Грузоподъёмность до 5 т', 'Вылет 52 м, на конце ~1 т', 'Наращивание мачты секциями'], 'price': None}, {'subslug': 'qe-mct132', 'name': 'Кран 6 т, стрела 60 м (класс Potain MCT 132)', 'specs': ['Грузоподъёмность до 6 т', 'Вылет до 60 м', 'Монтаж автокраном за 1–2 дня'], 'price': None}, {'subslug': 'qe-130ecb', 'name': 'Кран 8 т, стрела 55 м (класс Liebherr 130 EC-B)', 'specs': ['Грузоподъёмность до 8 т', 'Вылет 55 м, плоская вершина (flat-top)', 'Работа в группе кранов на площадке'], 'price': None}, {'subslug': 'qe-mdt219', 'name': 'Кран 10 т, стрела 65 м (класс Potain MDT 219)', 'specs': ['Грузоподъёмность до 10 т', 'Вылет до 65 м', 'Приставной, высота под крюк 60+ м'], 'price': None}, {'subslug': 'qe-comansa', 'name': 'Кран 6 т, стрела 45 м (класс Comansa 5LC / Terex)', 'specs': ['Грузоподъёмность до 6 т', 'Вылет 45 м', 'Компактная сборка на стеснённой площадке'], 'price': None}, {'subslug': 'qe-heavy', 'name': 'Кран 12 т, стрела 60 м (тяжёлый flat-top)', 'specs': ['Грузоподъёмность до 12 т', 'Вылет до 60 м', 'Частотный привод, большой грузовой момент'], 'price': None}], 'faqs': [['Чем быстромонтируемый отличается от самомонтирующегося?', 'Самомонтирующийся раскладывается сам за часы, но ограничен по высоте и грузу. Быстромонтируемый собирают автокраном из блоков за 1–2 дня — зато он выше, берёт тяжелее и даёт больший вылет. Выбор зависит от этажности и веса грузов.'], ['Сколько нужно на монтаж и что подготовить?', 'Обычно 1–2 дня на сборку и наладку. Нужны фундамент или балластное основание по расчёту, подъездной путь для автокрана и трала, питание 380 В и согласованная зона монтажа.'], ['Можно нарастить высоту по мере роста здания?', 'Да, у большинства моделей мачта наращивается секциями, в том числе приставным и самоподъёмным способом. Требуемую высоту под крюк заложим ещё при подборе.'], ['Как считается аренда и что входит?', 'Аренда помесячная на объект. В договор закладываем доставку, монтаж, демонтаж, оператора и обслуживание. Стоимость зависит от модели, высоты, вылета и срока — посчитаем под ваш проект.'], ['Кто отвечает за ОПО, ППРк и допуски?', 'Предоставляем полный пакет по опасному производственному объекту: паспорта, ППРк, аттестованного крановщика и стропальщиков. Помогаем с уведомлением Ростехнадзора и допуском на площадку.']]},
  {'slug': 'kozlovye-krany', 'name_nom': 'Козловые краны', 'name_single': 'Козловой кран', 'h1': 'Аренда и поставка козлового крана', 'lead': 'Козловые краны грузоподъёмностью от 5 до 50 тонн с пролётом до 32 метров. Подберём, поставим и смонтируем кран под ваш склад, площадку или производство из проверенной сети производителей и подрядчиков по России.', 'intro': 'Козловой кран — мостовая конструкция на двух опорах-«ногах», перемещающаяся по наземным рельсам (или на пневмоходу). Работает на открытых площадках и складах, где невыгодно строить эстакаду под мостовой кран: базы хранения, производства ЖБИ и пиломатериалов, контейнерные и грузовые терминалы, монтаж оборудования. Перекрывает большие пролёты и может иметь консоли для выноса груза за пределы рельсов. Отличается высокой грузоподъёмностью на всём пролёте и работой без опоры на здание.', 'price_from': None, 'items': [{'subslug': 'kk-5t', 'name': 'Козловой кран 5 т, пролёт до 16 м (класс КК-5)', 'specs': ['Грузоподъёмность 5 т', 'Пролёт 12–16 м, высота подъёма до 9 м', 'Электроталь, управление с пола или по радио'], 'price': None}, {'subslug': 'kk-10t', 'name': 'Козловой кран 10 т, пролёт до 16 м (класс ККС-10)', 'specs': ['Грузоподъёмность 10 т', 'Пролёт до 16 м, две консоли', 'Тельферный или с грузовой тележкой'], 'price': None}, {'subslug': 'kk-12t', 'name': 'Козловой кран 12,5 т, пролёт до 25 м', 'specs': ['Грузоподъёмность 12,5 т', 'Пролёт до 25 м', 'Двухбалочная схема, кабина или радиоуправление'], 'price': None}, {'subslug': 'kk-20t', 'name': 'Козловой кран 20 т, пролёт до 32 м (класс КК-20)', 'specs': ['Грузоподъёмность 20 т', 'Пролёт до 32 м, консоли до 8 м', 'Для баз хранения и производств ЖБИ'], 'price': None}, {'subslug': 'kk-32t', 'name': 'Козловой кран 32 т, пролёт до 32 м (класс КК-32)', 'specs': ['Грузоподъёмность 32 т', 'Пролёт до 32 м', 'Двухбалочный, тяжёлый режим работы'], 'price': None}, {'subslug': 'kk-50t', 'name': 'Козловой кран 50 т (спецпроект)', 'specs': ['Грузоподъёмность 50 т и выше', 'Большой пролёт под задачу', 'Монтаж негабарита и тяжёлого оборудования'], 'price': None}, {'subslug': 'kk-container', 'name': 'Контейнерный козловой кран 40 т (RTG / RMG)', 'specs': ['Грузоподъёмность до 40 т под спредер', 'Пневмо- или рельсовый ход', 'Штабелирование контейнеров в 3–5 ярусов'], 'price': None}, {'subslug': 'kk-semi', 'name': 'Полукозловой кран 8 т', 'specs': ['Грузоподъёмность 8 т', 'Одна нога на полу, вторая на эстакаде', 'Экономит площадь у стены цеха'], 'price': None}], 'faqs': [['Козловой кран — это аренда или поставка с монтажом?', 'Чаще это проектная поставка: подбираем кран под пролёт и груз, поставляем, монтируем на подкрановые пути и сдаём в работу. Возможна и аренда на срок проекта — обсудим формат под задачу.'], ['Как подобрать кран под площадку?', 'Нужны грузоподъёмность, требуемый пролёт (расстояние между рельсами), высота подъёма, наличие консолей и режим работы. По ним подберём схему (одно- или двухбалочный, с консолями) и рассчитаем нагрузки на пути.'], ['Нужны ли рельсовые пути и фундамент?', 'Для рельсовых кранов — да, нужны подкрановые пути на подготовленном основании; поможем с расчётом и устройством. Для мобильных задач есть пневмоколёсные (RTG) варианты, не требующие рельсов.'], ['Управление с земли или из кабины?', 'В зависимости от модели — из кабины, с пола по кнопочному пульту или по радио. Для складских операций чаще ставим радиоуправление, чтобы оператор видел груз и стропальщика.'], ['Оператор, документы, регистрация ОПО?', 'Предоставляем аттестованных операторов и стропальщиков, паспорта и документы на кран, ППР. Кран — объект Ростехнадзора: поможем с постановкой на учёт, пусконаладкой и техническим освидетельствованием.']]},
  {'slug': 'mostovye-krany', 'name_nom': 'Мостовые краны', 'name_single': 'Мостовой кран', 'h1': 'Мостовые краны — подбор, поставка и монтаж', 'lead': 'Мостовые краны грузоподъёмностью от 3,2 до 50 тонн с пролётом до 34,5 метра. Подберём кран под ваш пролёт, высоту подъёма и режим работы и организуем поставку с шеф-монтажом из проверенной партнёрской сети.', 'intro': 'Мостовой кран — грузоподъёмная машина, у которой несущий мост перемещается по подкрановым путям вдоль цеха, а грузовая тележка с талью или лебёдкой ходит поперёк моста. Такая схема перекрывает всю площадь пролёта и не занимает пол, поэтому мостовые краны — основа внутрицехового подъёма в машиностроении, металлургии, на складах и в ремонтных депо. Ключевые различия: опорные (мост опирается сверху на рельсы подкрановых балок) и подвесные (мост катится по нижним полкам путей, подвешенных к перекрытию); однобалочные (лёгкие и средние режимы, таль-тельфер) и двухбалочные (средние и тяжёлые режимы, крановая тележка, большие высоты подъёма). Управление — с пола (кнопочный пульт), из кабины или по радио. Подбор ведут по грузоподъёмности, пролёту, высоте подъёма и группе режима работы (по ИСО 4301 / ГОСТ 34017).', 'price_from': None, 'items': [{'subslug': 'odnobalochnyy-opornyy-5t', 'name': 'Однобалочный опорный, 5 т', 'specs': ['Грузоподъёмность 5 т', 'Пролёт 10,5–16,5 м', 'Высота подъёма до 8 м, управление с пола'], 'price': None}, {'subslug': 'odnobalochnyy-opornyy-10t', 'name': 'Однобалочный опорный, 10 т', 'specs': ['Грузоподъёмность 10 т', 'Пролёт 16,5–22,5 м', 'Электротельфер, режим A3–A4'], 'price': None}, {'subslug': 'podvesnoy-3-2t', 'name': 'Подвесной однобалочный, 3,2 т', 'specs': ['Грузоподъёмность 3,2 т', 'Пролёт 9–15 м', 'Крепление к перекрытию, одно- и двухпролётное исполнение'], 'price': None}, {'subslug': 'dvuhbalochnyy-opornyy-16t', 'name': 'Двухбалочный опорный, 16 т', 'specs': ['Грузоподъёмность 16 т', 'Пролёт до 28 м', 'Высота подъёма до 12 м, кабина или радиоуправление'], 'price': None}, {'subslug': 'dvuhbalochnyy-opornyy-32t', 'name': 'Двухбалочный опорный, 32/5 т', 'specs': ['Главный крюк 32 т, вспомогательный 5 т', 'Пролёт до 34 м', 'Тяжёлый режим A6–A7, две скорости подъёма'], 'price': None}, {'subslug': 'dvuhbalochnyy-50t', 'name': 'Двухбалочный опорный, 50 т', 'specs': ['Грузоподъёмность 50 т', 'Пролёт до 34,5 м', 'Ремонтно-монтажный/литейный, частотный привод'], 'price': None}, {'subslug': 'greyfernyy-magnitnyy', 'name': 'Грейферный / магнитный', 'specs': ['Грузоподъёмность 5–20 т', 'Пролёт по проекту цеха', 'Навесной грейфер или электромагнит, круглосуточный режим'], 'price': None}, {'subslug': 'kran-shtabeler', 'name': 'Кран-штабелёр (специальный)', 'specs': ['Грузоподъёмность 1–5 т', 'Высота обслуживания стеллажей до 12 м', 'Жёсткая колонна с захватом, точная адресация ячеек'], 'price': None}], 'faqs': [['Как правильно подобрать мостовой кран?', 'Нужны четыре параметра: масса самого тяжёлого груза (грузоподъёмность), расстояние между осями подкрановых путей (пролёт), требуемая высота подъёма и интенсивность работы (группа режима). По ним мы подбираем однобалочный или двухбалочный кран, опорное или подвесное исполнение и тип управления. Достаточно прислать эти данные или чертёж/фото цеха — вернёмся с вариантами.'], ['Кран приедет готовым или его собирают на месте?', 'Мостовой кран — стационарное оборудование: на объект привозят мост, тележку, механизмы и токоподвод, а сборку и наладку ведут на подкрановых путях. Если путей ещё нет, подбираем и монтаж балок с рельсами. Организуем поставку и шеф-монтаж силами проверенных партнёров, сроки фиксируем в договоре.'], ['Нужны ли подготовленные подкрановые пути и что с монтажом-демонтажом?', 'Да, опорному крану нужны подкрановые балки с рельсами и токоподвод, подвесному — закладные под перекрытием. Мы оцениваем готовность здания, при необходимости включаем в проект пути, монтаж крана, пусконаладку и сдачу. Демонтаж и перенос крана на другой объект тоже организуем.'], ['Даёте оператора (машиниста) и стропальщиков?', 'Краны с управлением с пола или по радио может вести аттестованный сотрудник заказчика после инструктажа; для кранов с кабиной нужен машинист крана. По запросу подбираем аттестованный персонал — машиниста и стропальщиков — вместе с техникой.'], ['Какие документы оформляются на мостовой кран?', 'На кран передаётся паспорт, руководство по эксплуатации, сертификаты и акт монтажа/пусконаладки; кран как ОПО-оборудование ставится на учёт и проходит техническое освидетельствование. Комплект документов и участие в пусконаладке обеспечиваем при поставке.']]},
  {'slug': 'portalnye-krany', 'name_nom': 'Портальные краны', 'name_single': 'Портальный кран', 'h1': 'Портальные краны — подбор и организация поставки', 'lead': 'Организуем подбор и поставку портального крана нужной грузоподъёмности и вылета для порта, судоверфи или строительной площадки — из проверенной партнёрской сети, с ответственностью за сроки по договору.', 'intro': 'Портальный кран — это полноповоротный стреловой кран, установленный на портале: высокой раме на опорах-«ногах», которая катится по рельсовому пути. Под порталом свободно проходят железнодорожные пути или автотранспорт, поэтому кран одновременно и перегружает груз, и не перекрывает движение внизу. Основная сфера — перегрузка в морских и речных портах (крюковая и грейферная работа с навалочными и штучными грузами, контейнерами), судостроение и судоремонт, гидротехническое и мостовое строительство. От башенных и мостовых кранов портальные отличают большой вылет стрелы (обычно 25–40 м), шарнирно-сочленённая или качающаяся стрела с горизонтальным перемещением груза и высокая производительность в интенсивном режиме. Подбор ведут по грузоподъёмности на максимальном вылете, диапазону вылетов, высоте подъёма и типу рабочего органа (крюк, грейфер, спредер).', 'price_from': None, 'items': [{'subslug': 'peregruzochnyy-albatros-10t', 'name': 'Перегрузочный «Альбатрос», 10 т', 'specs': ['Грузоподъёмность 10 т', 'Вылет 8–32 м', 'Крюк/грейфер, колея портала под ж/д путь'], 'price': None}, {'subslug': 'peregruzochnyy-kondor-16t', 'name': 'Перегрузочный «Кондор», 16 т', 'specs': ['Грузоподъёмность 16 т', 'Вылет до 32 м', 'Грейферный режим, высокая производительность на навалке'], 'price': None}, {'subslug': 'ganz-6t', 'name': '«Ганц» (Ganz), 5–6 т', 'specs': ['Грузоподъёмность 5–6 т', 'Вылет до 30 м', 'Классический портал для штучных и навалочных грузов'], 'price': None}, {'subslug': 'kirovets-30t', 'name': '«Кировец», 5–30 т', 'specs': ['Грузоподъёмность 5–30 т (в зависимости от исполнения)', 'Вылет до 30 м', 'Универсальная перегрузка, крюк или грейфер'], 'price': None}, {'subslug': 'kryukovoy-32t', 'name': 'Крюковой перегрузочный, 32 т', 'specs': ['Грузоподъёмность 32 т', 'Вылет 10–32 м', 'Тяжёлые штучные и проектные грузы, тарные партии'], 'price': None}, {'subslug': 'montazhnyy-80t', 'name': 'Монтажный портальный, 80 т', 'specs': ['Грузоподъёмность до 80 т', 'Вылет до 25 м', 'Монтаж металлоконструкций и гидросооружений'], 'price': None}, {'subslug': 'sudostroitelnyy-80t', 'name': 'Судостроительный, до 80 т', 'specs': ['Грузоподъёмность до 80 т', 'Большая высота подъёма над стапелем', 'Сборка секций корпуса на верфи'], 'price': None}], 'faqs': [['По каким параметрам подбирают портальный кран?', 'Ключевое — грузоподъёмность именно на максимальном вылете (а не только у стойки), диапазон вылетов, высота подъёма над причалом/стапелем и вид работы: крюк, грейфер или спредер. Также важна колея и радиус закругления рельсового пути. Пришлите задачу и параметры площадки — подберём подходящую модель и исполнение.'], ['Портальный кран поставляется целиком или монтируется на месте?', 'Это крупногабаритное оборудование, которое доставляется секциями и собирается на подкрановом рельсовом пути. Нужен подготовленный путь с фундаментом и токоподводом. Организуем поставку, укрупнительную сборку, монтаж и пусконаладку через проверенных подрядчиков; объём и сроки фиксируем в договоре.'], ['Что нужно для установки — какой фундамент и пути?', 'Порталу требуется рельсовый путь на свайном или монолитном основании, рассчитанный на нагрузку от опор, и линия питания. Оцениваем причал/площадку, при необходимости включаем в проект устройство путей и электроснабжение. Демонтаж и перебазирование крана также берём на себя.'], ['Кто управляет портальным краном?', 'Работу ведёт аттестованный крановщик (машинист портального крана) из кабины, совместно со стропальщиками и сигнальщиком. Подбираем аттестованный экипаж вместе с техникой либо обучаем и допускаем персонал заказчика по согласованию.'], ['Можно ли взять портальный кран в аренду на проект?', 'Портальные краны — преимущественно капитальное перегрузочное оборудование, поэтому чаще это поставка с монтажом, а не посменная аренда. Для разовых монтажных задач под большой вылет нередко выгоднее гусеничный или автокран — подскажем оптимальный вариант под конкретную работу.']]},
  {'slug': 'kran-balki-konsolnye-krany', 'name_nom': 'Кран-балки и консольные краны', 'name_single': 'Кран-балка', 'h1': 'Кран-балки и консольные краны — подбор и поставка', 'lead': 'Кран-балки грузоподъёмностью от 1 до 5 тонн с пролётом до 16,5 метра и консольные краны от 0,25 до 2 тонн с вылетом до 5 метров. Подберём под ваш участок и организуем поставку с монтажом из проверенной сети.', 'intro': 'Кран-балка — это лёгкий однобалочный кран, у которого несущая балка перемещается по подкрановым путям, а вдоль балки ходит электроталь (тельфер) с грузом. Бывает опорной (балка катится по верху рельсов подкрановых путей) и подвесной (балка подвешена к нижним полкам путей, закреплённых под перекрытием) — подвесная удобнее в невысоких помещениях и даёт возможность стыковать соседние пролёты. Консольный (поворотный, jib) кран решает другую задачу: обслуживает локальную рабочую зону в радиусе поворота стрелы-консоли. Его ставят на колонну (напольный, с поворотом до 270–360°), крепят к стене (настенный) или к колонне цеха. Такие краны применяют на рабочих местах у станков, в сборочных и ремонтных зонах, малых складах, для загрузки оборудования и обслуживания конвейеров — там, где мостовой кран избыточен. Подбор ведут по грузоподъёмности, пролёту (для кран-балки) или вылету и углу поворота (для консольного крана) и высоте подъёма.', 'price_from': None, 'items': [{'subslug': 'kran-balka-podvesnaya-1t', 'name': 'Кран-балка подвесная, 1 т', 'specs': ['Грузоподъёмность 1 т', 'Пролёт 3–9 м', 'Крепление к перекрытию, управление с пола'], 'price': None}, {'subslug': 'kran-balka-opornaya-3-2t', 'name': 'Кран-балка опорная, 3,2 т', 'specs': ['Грузоподъёмность 3,2 т', 'Пролёт 6–12 м', 'Электроталь, высота подъёма до 6 м'], 'price': None}, {'subslug': 'kran-balka-opornaya-5t', 'name': 'Кран-балка опорная, 5 т', 'specs': ['Грузоподъёмность 5 т', 'Пролёт до 16,5 м', 'Режим A3–A4, кнопочный или радиопульт'], 'price': None}, {'subslug': 'konsolnyy-na-kolonne-0-5t', 'name': 'Консольный на колонне, 0,5 т', 'specs': ['Грузоподъёмность 0,5 т', 'Вылет 3–4 м', 'Поворот 270°, обслуживание рабочего места'], 'price': None}, {'subslug': 'konsolnyy-na-kolonne-2t', 'name': 'Консольный на колонне, 2 т', 'specs': ['Грузоподъёмность 2 т', 'Вылет 4–5 м', 'Поворот 360°, ручной или электроповорот'], 'price': None}, {'subslug': 'konsolnyy-nastennyy-1t', 'name': 'Консольный настенный, 1 т', 'specs': ['Грузоподъёмность 1 т', 'Вылет 3–4 м', 'Крепление к стене/колонне, экономит площадь пола'], 'price': None}, {'subslug': 'konsolnyy-peredvizhnoy-0-25t', 'name': 'Консольный передвижной, 0,25 т', 'specs': ['Грузоподъёмность 0,25 т', 'Вылет до 3 м', 'Перемещение вдоль настенного пути'], 'price': None}], 'faqs': [['Чем кран-балка отличается от консольного крана и что выбрать?', 'Кран-балка перекрывает весь пролёт помещения и перемещает груз по всей его площади — она нужна, когда работать надо по всему участку. Консольный кран обслуживает локальную зону в радиусе поворота стрелы и удобен у отдельного станка или рабочего места. Опишите задачу и размеры участка — предложим оптимальный вариант.'], ['Кран поставляется в сборе или монтируется на объекте?', 'Кран-балку и консольный кран привозят комплектом (балка/консоль, таль, пути или колонна, токоподвод) и собирают на месте. Опорной кран-балке нужны подкрановые пути, подвесной — закладные под перекрытием, консольному — фундамент под колонну или закладные в стене. Организуем поставку и монтаж под ключ.'], ['Что требуется для установки консольного крана?', 'Для крана на колонне — фундамент под расчётную нагрузку и подвод питания; для настенного — несущая стена или колонна с закладными. Мы оцениваем готовность площадки, при необходимости включаем в проект фундамент и электрику, выполняем монтаж и пусконаладку.'], ['Кто может управлять кран-балкой?', 'Кран-балки и консольные краны с управлением с пола (кнопочный пульт или радио) ведёт сотрудник заказчика, аттестованный как оператор напольного управления и стропальщик, после инструктажа. По запросу подбираем аттестованный персонал вместе с оборудованием.'], ['Какие документы идут с краном?', 'Комплект включает паспорт крана и тали, руководство по эксплуатации, сертификаты соответствия и акт монтажа/пусконаладки. Кран ставится на учёт и проходит техническое освидетельствование перед пуском — сопровождаем оформление при поставке.']]},
  {'slug': 'zheleznodorozhnye-krany', 'name_nom': 'Железнодорожные краны', 'name_single': 'Железнодорожный кран', 'h1': 'Железнодорожные краны — подбор и подача на объект', 'lead': 'Железнодорожные краны грузоподъёмностью от 16 до 125 тонн с вылетом до 16 метров. Подберём кран и подадим на ваш участок пути через проверенную партнёрскую сеть; техника — с аттестованным экипажем.', 'intro': 'Железнодорожный кран — самоходный полноповоротный стреловой кран на рельсовом ходу: он передвигается по колее локомотивной тягой или своим ходом, а работает с выносных опор (аутригеров), которые снимают нагрузку с ходовых тележек. Такие краны применяют на восстановительных и аварийных работах (подъём сошедшего с рельсов подвижного состава), при укладке и ремонте пути, монтаже мостов и контактной сети, погрузочно-разгрузочных операциях на станциях и подъездных путях промышленных предприятий. Отличительные черты — работа строго в габарите приближения строений, грузоподъёмность, сильно зависящая от вылета и положения (вдоль или поперёк пути), и наличие противовеса для тяжёлых режимов. Распространённые семейства: отечественные КДЭ, КЖ, КЖДЭ и немецкие ЕДК (Kirow). Подбор ведут по грузоподъёмности на рабочем вылете, длине стрелы, высоте подъёма и допуску к конкретной инфраструктуре.', 'price_from': None, 'items': [{'subslug': 'kde-163-16t', 'name': 'КДЭ-163, 16 т', 'specs': ['Грузоподъёмность 16 т', 'Вылет 4,5–14 м', 'Дизель-электрический, погрузка и путевые работы'], 'price': None}, {'subslug': 'kzhde-16-16t', 'name': 'КЖДЭ-16, 16 т', 'specs': ['Грузоподъёмность 16 т', 'Вылет до 14 м', 'Выносные опоры, работа со стрелой вдоль/поперёк пути'], 'price': None}, {'subslug': 'kzhde-25-25t', 'name': 'КЖДЭ-25, 25 т', 'specs': ['Грузоподъёмность 25 т', 'Вылет 4,5–14 м', 'Погрузо-разгрузочные и монтажные работы на станциях'], 'price': None}, {'subslug': 'kzh-971-25t', 'name': 'КЖ-971, 25 т', 'specs': ['Грузоподъёмность 25 т', 'Удлинённая стрела, увеличенная высота подъёма', 'Монтаж мостов и контактной сети'], 'price': None}, {'subslug': 'edk-300-60t', 'name': 'ЕДК-300/2 (Kirow), 60 т', 'specs': ['Грузоподъёмность до 60 т', 'Вылет до 16 м с противовесом', 'Восстановительные работы, подъём подвижного состава'], 'price': None}, {'subslug': 'edk-500-80t', 'name': 'ЕДК-500 (Kirow), 80 т', 'specs': ['Грузоподъёмность до 80 т', 'Работа с подвижным и неподвижным противовесом', 'Аварийно-восстановительные поезда'], 'price': None}, {'subslug': 'edk-1000-125t', 'name': 'ЕДК-1000 (Kirow), 125 т', 'specs': ['Грузоподъёмность до 125 т', 'Большой вылет с балластом', 'Тяжёлые восстановительные и мостовые работы'], 'price': None}, {'subslug': 'kzh-462-16t', 'name': 'КЖ-462, 16 т', 'specs': ['Грузоподъёмность 16 т', 'Вылет до 14 м', 'Универсальный станционный кран, крюк/грейфер'], 'price': None}], 'faqs': [['Как подобрать железнодорожный кран под задачу?', 'Определяющие параметры — масса груза и рабочий вылет (грузоподъёмность резко падает с увеличением вылета и различается при работе стрелой вдоль или поперёк пути), требуемая высота подъёма и характер работы: погрузка, путевые работы, монтаж или подъём подвижного состава. Пришлите задачу и место работ — подберём модель и исполнение.'], ['Как кран попадает на объект — своим ходом или доставкой?', 'Железнодорожный кран перемещается по колее в составе поезда (локомотивной тягой) или самоходом на короткие расстояния. Подача возможна только при наличии доступа к путям и согласования с владельцем инфраструктуры. Организуем подачу на ваш участок или подъездной путь через проверенных партнёров, сроки фиксируем в договоре.'], ['Что нужно для работы крана на путях (опоры, габарит, допуски)?', 'Кран работает с выносных опор на подготовленной площадке у пути и строго в габарите приближения строений; при работе рядом с действующими путями и контактной сетью нужны согласования, «окно» в движении и снятие напряжения. Помогаем спланировать работы и подготовить необходимые согласования с эксплуатирующей организацией.'], ['Кран приходит с оператором?', 'Да, железнодорожный кран подаётся с аттестованным машинистом (крановщиком) и, при необходимости, помощником и стропальщиками — это спецтехника повышенной опасности, самостоятельная эксплуатация без допуска не предусмотрена. Экипаж входит в подачу.'], ['Какие документы оформляются на работу ЖД-крана?', 'На кран есть паспорт, свидетельство о техническом освидетельствовании и допуск персонала; на сами работы оформляются ППР (проект производства работ), наряд-допуск и согласование с владельцем инфраструктуры, при работах у контактной сети — на снятие напряжения. Комплект под конкретный объект помогаем подготовить.']]},
]
